using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Collections.Generic;
using System.Text;

public static void Exec(Quicker.Public.IStepContext context){
	Int64 userSelect = Convert.ToInt64(context.GetVarValue("userSelect"));
	Int64 curId = Convert.ToInt64(context.GetVarValue("id"));
	
    List<String> topProcessList = new List<String>();
	List<WindowInfo> hWndList = EnumWindowsCallback();
	for (int j = 0; j < hWndList.Count; j++){
		WindowInfo info = hWndList[j];
		IntPtr hWnd = info.hWnd;
		if(userSelect == 1 && curId == (int)hWnd){
			continue;
		}
		if(!HasMainWindow(hWnd)){
			continue;
		}
		if(SetNoTopMost(hWnd)){
			topProcessList.Add(info.titleName);
		}
	}
	
	context.SetVarValue("hasCancelTop", topProcessList.Count > 0);
	context.SetVarValue("topMsg", String.Join("\n", topProcessList.ToArray()));
}

private const int HWND_NOTOPMOST = (-2);
private const int HWND_TOPMOST = (-1);

private const uint SWP_NOSIZE = 0x1;
private const uint SWP_NOMOVE = 0x2;
private const uint SWP_SHOWWINDOW = 0x40;
private const uint SWP_NOACTIVATE = 0x0010;

private const int GWL_EXSTYLE = (-20);
private const int GWL_STYLE = (-16);
private const int WS_EX_TOPMOST = 0x00000008;
private const int WS_VISIBLE = 0x10000000;

public delegate bool WNDENUMPROC(IntPtr hWnd, int lParam);

[DllImport("user32.dll", SetLastError = true)]
public static extern IntPtr GetShellWindow();

[DllImport("user32.dll", SetLastError = true)]
public static extern bool IsWindowVisible(IntPtr hWnd);

[DllImport("user32.dll", SetLastError = true)]
public static extern int GetWindowLongPtr(IntPtr hWnd, int nIndex);

[DllImport("user32.dll", ExactSpelling = true)]
public static extern bool EnumWindows(WNDENUMPROC lpEnumFunc, int lParam);

[DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Auto)]
public static extern int GetWindowTextLength(IntPtr hWnd);

[DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
public static extern int GetWindowTextW(IntPtr hWnd, [MarshalAs(UnmanagedType.LPWStr)]StringBuilder lpString, int nMaxCount);

[DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
public static extern int GetWindowThreadProcessId(IntPtr hWnd, out uint processId);    

[DllImport("user32.dll", SetLastError = true)]
public static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);

public struct WindowInfo{
	public IntPtr hWnd;
	public string titleName;
}

public static bool HasMainWindow(IntPtr hWnd){
	uint pid = 0;
    GetWindowThreadProcessId(hWnd, out pid );
	if (pid == 0) return false;
	Process process = Process.GetProcessById((int)pid);
	if (process == null || (IntPtr)process.MainWindowHandle == IntPtr.Zero) {
	    return false;
	}
	return true;
}

public static List<WindowInfo> EnumWindowsCallback(){
	IntPtr shellWindow = GetShellWindow();
    List<WindowInfo> hWndList = new List<WindowInfo>();
    EnumWindows(delegate(IntPtr hWnd, int lParam){
    	if (hWnd == shellWindow) return true;
      	if (!IsWindowVisible(hWnd)) return true;
    	int length = GetWindowTextLength(hWnd);
    	if (length == 0) return true;
    	
    	StringBuilder title = new StringBuilder(length+1);
    	GetWindowTextW(hWnd, title, title.Capacity);
		WindowInfo info = new WindowInfo();
    	info.hWnd = hWnd;
    	info.titleName = title.ToString();
        hWndList.Add(info);
        return true;
    }, 0);
    return hWndList;
}

public static bool CheckIsTopMost(IntPtr hWnd){
	int dwExStyle = GetWindowLongPtr(hWnd, GWL_EXSTYLE);
	int style = GetWindowLongPtr(hWnd, GWL_STYLE);
	if ((dwExStyle & WS_EX_TOPMOST) == WS_EX_TOPMOST && (style & WS_VISIBLE) == WS_VISIBLE){
		return true;
	}
	return false;
}

public static bool SetNoTopMost(IntPtr hWnd){
	if(!CheckIsTopMost(hWnd)){
		return false;
	}
	return SetWindowPos(hWnd, (IntPtr)HWND_NOTOPMOST, 0, 0, 0, 0, SWP_NOMOVE|SWP_NOSIZE|SWP_NOACTIVATE);
